import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.Bx7X8BVG.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1790778157000}'),n={name:"guide/faq.md"};function l(r,a,o,h,d,p){return s(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="隧道相关" tabindex="-1">隧道相关 <a class="header-anchor" href="#隧道相关" aria-label="Permalink to &quot;隧道相关&quot;">​</a></h2><h3 id="隧道点了连接就断开-cloudflared-启动即退出" tabindex="-1">隧道点了连接就断开 / cloudflared 启动即退出 <a class="header-anchor" href="#隧道点了连接就断开-cloudflared-启动即退出" aria-label="Permalink to &quot;隧道点了连接就断开 / cloudflared 启动即退出&quot;">​</a></h3><p>按顺序排查：</p><ol><li><strong>凭据对不对</strong>：「系统配置」里重填 Account ID + API Token，点「测试配置」确认通过</li><li><strong>云端隧道还在不在</strong>：如果这个隧道在 Cloudflare 后台被删过，本地记录就是空壳，删掉重建一条</li><li><strong>协议问题</strong>：有些网络屏蔽 UDP，把「连接参数 → 协议」从 <code>QUIC</code> 改成 <code>HTTP2</code></li><li><strong>看日志</strong>：「运行日志」页会<strong>把真正的错误行提取置顶</strong>，先看那一行</li></ol><h3 id="面板显示「云端在线-本地离线」" tabindex="-1">面板显示「云端在线，本地离线」 <a class="header-anchor" href="#面板显示「云端在线-本地离线」" aria-label="Permalink to &quot;面板显示「云端在线，本地离线」&quot;">​</a></h3><p>这说明 Cloudflare 云端认为隧道活跃，但<strong>你这台机器上并没有对应进程在跑</strong>——通常是：</p><ul><li>面板刚重启，隧道还没自动连上（等几秒或点一下「连接」）</li><li>之前连接过又手动断开了</li><li>这条隧道实际跑在<strong>另一台设备</strong>上（筛选条里会标 🏠 本机 / ☁️ 其他设备）</li></ul><p>以「本地」状态为准——只有本地进程真的在跑、并且日志出现 <code>Registered tunnel connection</code> 才是真的通了。</p><h3 id="同一条隧道能同时连多次吗" tabindex="-1">同一条隧道能同时连多次吗？ <a class="header-anchor" href="#同一条隧道能同时连多次吗" aria-label="Permalink to &quot;同一条隧道能同时连多次吗？&quot;">​</a></h3><p>不要。同一条隧道在多个地方跑会导致边缘连接来回抖动。多条<strong>不同</strong>隧道同时在线才是这个项目支持的场景。</p><h2 id="域名与-dns" tabindex="-1">域名与 DNS <a class="header-anchor" href="#域名与-dns" aria-label="Permalink to &quot;域名与 DNS&quot;">​</a></h2><h3 id="自定义域名能用-https-吗" tabindex="-1">自定义域名能用 HTTPS 吗？ <a class="header-anchor" href="#自定义域名能用-https-吗" aria-label="Permalink to &quot;自定义域名能用 HTTPS 吗？&quot;">​</a></h3><p>能。添加转发规则时面板会自动创建 <strong>CNAME 记录并开启橙云代理</strong>（proxied）。此时：</p><ul><li>访问 <code>https://你的域名</code> 由 Cloudflare 边缘直接提供证书，<strong>不用自己申请</strong></li><li>你的真实出口 IP 被隐藏</li></ul><h3 id="同一个内网服务能同时挂「随机域名」和「自定义域名」吗" tabindex="-1">同一个内网服务能同时挂「随机域名」和「自定义域名」吗？ <a class="header-anchor" href="#同一个内网服务能同时挂「随机域名」和「自定义域名」吗" aria-label="Permalink to &quot;同一个内网服务能同时挂「随机域名」和「自定义域名」吗？&quot;">​</a></h3><p>可以。在隧道的路由规则里加<strong>两条规则</strong>指向同一个内网服务即可，例如：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>abc123xyz.example.com   →  http://192.168.1.10:5000</span></span>\n<span class="line"><span>nas.example.com         →  http://192.168.1.10:5000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>调试期常用这个做法：先用随机域名验证通了，再换正式域名。</p><h3 id="删除隧道会删掉-dns-记录吗" tabindex="-1">删除隧道会删掉 DNS 记录吗？ <a class="header-anchor" href="#删除隧道会删掉-dns-记录吗" aria-label="Permalink to &quot;删除隧道会删掉 DNS 记录吗？&quot;">​</a></h3><p>不会自动清理。删隧道只删云端隧道和本地记录，之前创建的 CNAME 会留在你的 DNS 里——需要的话去 Cloudflare 后台手动删。</p><h3 id="普通用户点「🎲」提示「请先设置默认域名」" tabindex="-1">普通用户点「🎲」提示「请先设置默认域名」 <a class="header-anchor" href="#普通用户点「🎲」提示「请先设置默认域名」" aria-label="Permalink to &quot;普通用户点「🎲」提示「请先设置默认域名」&quot;">​</a></h3><p>默认域名是<strong>管理员在「系统配置 → 默认域名」里设置一次</strong>的，普通用户会继承这个设置。出现这个提示说明管理员还没设，或者刚设置完页面还没刷新（刷新一下即可）。</p><h2 id="更新相关" tabindex="-1">更新相关 <a class="header-anchor" href="#更新相关" aria-label="Permalink to &quot;更新相关&quot;">​</a></h2><h3 id="git-fetch-报-http-2-stream-1-was-not-closed-cleanly" tabindex="-1"><code>git fetch</code> 报 <code>HTTP/2 stream 1 was not closed cleanly</code> <a class="header-anchor" href="#git-fetch-报-http-2-stream-1-was-not-closed-cleanly" aria-label="Permalink to &quot;`git fetch` 报 `HTTP/2 stream 1 was not closed cleanly`&quot;">​</a></h3><p>国内直连 GitHub 的经典故障，与你的配置无关。用带镜像的命令更新：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.version=HTTP/1.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://v4.gh-proxy.org/https://github.com/lieren2012/cloudflare-tunnel-manager.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FETCH_HEAD</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>或者直接 <code>bash update.sh</code>，脚本会自动切换可用镜像。</p><h3 id="更新完版本号没变" tabindex="-1">更新完版本号没变 <a class="header-anchor" href="#更新完版本号没变" aria-label="Permalink to &quot;更新完版本号没变&quot;">​</a></h3><ol><li><strong>Ctrl + F5</strong> 强制刷新浏览器（前端有缓存）</li><li>确认容器真的重建了：<code>docker compose ps</code> 看启动时间</li><li>确认代码真的拉下来了：<code>git log --oneline -1</code></li><li>浏览器里看的是不是另一个端口 / 另一个容器的实例</li></ol><h3 id="拉取基础镜像很慢" tabindex="-1">拉取基础镜像很慢 <a class="header-anchor" href="#拉取基础镜像很慢" aria-label="Permalink to &quot;拉取基础镜像很慢&quot;">​</a></h3><p>项目默认走 <code>docker.1ms.run</code>。如果你的网络环境它也不快，在项目目录 <code>cp .env.example .env</code> 后改成别的加速站或官方源：</p><div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NODE_IMAGE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=node:22-alpine</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CLOUDFLARED_IMAGE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=cloudflare/cloudflared:latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="面板内「更新到最新版」按钮点不了" tabindex="-1">面板内「更新到最新版」按钮点不了 <a class="header-anchor" href="#面板内「更新到最新版」按钮点不了" aria-label="Permalink to &quot;面板内「更新到最新版」按钮点不了&quot;">​</a></h3><p><strong>第一次</strong>必须用命令行更新一次（旧容器没有源码挂载、没有新版镜像）。之后按钮就能一直用了。详见 <strong><a href="/cloudflare-tunnel-manager/guide/update">更新与国内加速</a></strong>。</p><h2 id="账户相关" tabindex="-1">账户相关 <a class="header-anchor" href="#账户相关" aria-label="Permalink to &quot;账户相关&quot;">​</a></h2><h3 id="忘记管理员密码了" tabindex="-1">忘记管理员密码了 <a class="header-anchor" href="#忘记管理员密码了" aria-label="Permalink to &quot;忘记管理员密码了&quot;">​</a></h3><p>给容器加环境变量 <code>ADMIN_PASSWORD</code>：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ADMIN_PASSWORD=你的临时密码</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>然后登录页<strong>用户名填 <code>master</code>（或留空）</strong>、密码填这个值。进去后在「用户管理」里重置正式密码。</p><h3 id="新注册的用户登录不了" tabindex="-1">新注册的用户登录不了 <a class="header-anchor" href="#新注册的用户登录不了" aria-label="Permalink to &quot;新注册的用户登录不了&quot;">​</a></h3><p>需要管理员在「用户管理」里<strong>点「通过」审核</strong>才能登录。这是防止陌生人注册的默认机制。</p><h3 id="能用多个人的账号管理各自的隧道吗" tabindex="-1">能用多个人的账号管理各自的隧道吗？ <a class="header-anchor" href="#能用多个人的账号管理各自的隧道吗" aria-label="Permalink to &quot;能用多个人的账号管理各自的隧道吗？&quot;">​</a></h3><p>能。第一个注册者是管理员，之后每个用户注册并经审核后，<strong>只能看到和管理自己创建的隧道</strong>；管理员看全部。</p><h2 id="部署相关" tabindex="-1">部署相关 <a class="header-anchor" href="#部署相关" aria-label="Permalink to &quot;部署相关&quot;">​</a></h2><h3 id="_19090-端口被占用" tabindex="-1">19090 端口被占用 <a class="header-anchor" href="#_19090-端口被占用" aria-label="Permalink to &quot;19090 端口被占用&quot;">​</a></h3><p>改 <code>docker-compose.yml</code> 或 <code>.env</code> 里的端口映射，或者直接改 <code>WEB_PORT</code> 环境变量。</p><h3 id="能不能不用-docker" tabindex="-1">能不能不用 Docker <a class="header-anchor" href="#能不能不用-docker" aria-label="Permalink to &quot;能不能不用 Docker&quot;">​</a></h3><p>可以，但需要本机已装 <code>cloudflared</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>（面板内一键更新依赖 git 工作区和源码目录，非 Docker 方式同样可用。）</p><h3 id="项目会把我-nas-上的信息传到哪吗" tabindex="-1">项目会把我 NAS 上的信息传到哪吗？ <a class="header-anchor" href="#项目会把我-nas-上的信息传到哪吗" aria-label="Permalink to &quot;项目会把我 NAS 上的信息传到哪吗？&quot;">​</a></h3><p>不会。所有凭据、用户、隧道配置都只存在你自己的 <code>data/</code> 目录，项目不含任何上报或统计逻辑。项目与 Cloudflare, Inc. 无关，非官方项目。</p><h2 id="还没解决" tabindex="-1">还没解决？ <a class="header-anchor" href="#还没解决" aria-label="Permalink to &quot;还没解决？&quot;">​</a></h2><p>去 <a href="https://github.com/lieren2012/cloudflare-tunnel-manager/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 提问，附上：版本号（关于页可见）、你的操作步骤、以及<strong>运行日志里置顶的那几行错误</strong>。</p>',55)])])}const k=e(n,[["render",l]]);export{u as __pageData,k as default};
